def maior_valor(valores):
    if not valores:
        return 'lista vazia'
    return max(valores)

assert maior_valor([3, 8, 1]) == 8
assert maior_valor([0, 0, 0]) == 0
assert maior_valor([-5, -2, -9]) == -2
assert maior_valor([]) == 'lista vazia'
assert maior_valor([10**9, 10**9 + 1]) == 10**9 + 1
